"""Builds seeds/curriculum.json: the sample courses used by `lms seed`.

Content is original, written to England's national curriculum and the sample
courses in the specification. Run: python3 seeds/build_seed.py
"""
import json
import pathlib

COURSES = []


def course(code, title, subject, key_stage, year, colour, exam, concepts, mocks=()):
    COURSES.append(dict(code=code, title=title, subject=subject, key_stage=key_stage, year_group=year,
                        colour=colour, exam=exam, concepts=concepts, mocks=list(mocks)))


def concept(code, title, unit, lesson, quiz, review, cards, help_idea, prereq=()):
    return dict(code=code, title=title, unit=unit, lesson=lesson, quiz=quiz, review=review,
                flashcards=[dict(front=f, back=b) for f, b in cards],
                help=dict(title=help_idea[0], body=help_idea[1]), prerequisites=list(prereq))


def lesson(read, steps, check, example, reflect, ideas):
    return dict(read=read, steps=steps, check=check, worked_example=example,
                reflect_prompt=reflect, reflect_ideas=ideas)


def choice(prompt, answer, wrong, explanation, hints=()):
    opts = [dict(label=answer, misconception=None)] + [dict(label=l, misconception=m) for l, m in wrong]
    # stable, non-alphabetical order so the key is not always first
    opts = opts[1:2] + opts[:1] + opts[2:] if len(opts) > 2 else opts[::-1]
    return dict(kind="choice", prompt=prompt, options=opts, answer=answer, explanation=explanation, hints=list(hints))


def num(prompt, answer, explanation, hints=(), wrong=()):
    return dict(kind="numeric", prompt=prompt, options=[dict(label=l, misconception=m) for l, m in wrong],
                answer=str(answer), explanation=explanation, hints=list(hints))


def text(prompt, answer, explanation, hints=()):
    return dict(kind="text", prompt=prompt, options=[], answer=answer, explanation=explanation, hints=list(hints))


